use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl ExpectFile { # [doc = " Checks if file contents is equal to `actual`."] pub fn assert_eq (& self , actual : & str) { let expected = self . data () ; if actual == expected { return ; } Runtime :: fail_file (self , & expected , actual) ; } # [doc = " Checks if file contents is equal to `format!(\"{:#?}\", actual)`."] pub fn assert_debug_eq (& self , actual : & impl fmt :: Debug) { let actual = format ! ("{:#?}\n" , actual) ; self . assert_eq (& actual) } # [doc = " Returns the content of this expect."] pub fn data (& self) -> String { fs :: read_to_string (self . abs_path ()) . unwrap_or_default () . replace ("\r\n" , "\n") } fn write (& self , contents : & str) { fs :: write (self . abs_path () , contents) . unwrap () } fn abs_path (& self) -> PathBuf { if self . path . is_absolute () { self . path . to_owned () } else { let dir = Path :: new (self . position) . parent () . unwrap () ; to_abs_ws_path (& dir . join (& self . path)) } } }
}